  const data = window.BLUEPRINT_DATA;
  if (!data || !Array.isArray(data.terms) || !Array.isArray(data.dictionaryTerms)) return;

  const normalize = (value) => String(value || '').toLowerCase().replace(/[\s_-]+/g, '').replace(/[^a-z0-9\u4e00-\u9fff]/g, '');
  const splitWords = (value) => String(value || '').replace(/([a-z0-9])([A-Z])/g, '$1 $2').replace(/([A-Z])([A-Z][a-z])/g, '$1 $2').replace(/([A-Za-z])([0-9])/g, '$1 $2').replace(/([0-9])([A-Za-z])/g, '$1 $2').match(/[A-Za-z][A-Za-z0-9]*|[0-9]+/g) || [];
  const translate = new Map(catalog.words.map((word) => [normalize(word.en), word.zh]));
  const curatedWords = new Map((data.wordGlossary || []).map((word) => [normalize(word.en), word]));
  for (const word of catalog.words) {
    const key = normalize(word.en);
    if (!key || curatedWords.has(key)) continue;
    const item = { en: word.en, zh: word.zh, note: 'Epic UE 5.8 Blueprint API 词条拆分释义；辅助记忆翻译。' };
    data.wordGlossary.push(item);
    curatedWords.set(key, item);
  }

  const references = data.dictionaryTerms;
  const learningByName = new Map(data.terms.map((term) => [normalize(term.en), term]));
  const referenceByName = new Map(references.map((term) => [normalize(term.en), term]));
  const usedIds = new Set([...data.terms, ...references].map((term) => Number(term.id)));
  const category = '参考 · Epic 蓝图 API UE 5.8';
